/**
 * Unit tests for prompt/executor-route-nudge (M170/#3127)
 *
 * Once-per-session advisory that points build-shaped prompts at the executor
 * skills. Self-gated by a session flag file, so tests use unique session ids.
 */

import { describe, expect, test } from 'vitest';
import type { HookInput } from '../../types.js';
import { executorRouteNudge } from '../../prompt/executor-route-nudge.js';

let seq = 0;
function makeInput(prompt: string, sessionId?: string): HookInput {
  seq += 1;
  return {
    tool_name: '',
    session_id: sessionId ?? `wf-nudge-test-${process.pid}-${Date.now()}-${seq}`,
    prompt,
  } as HookInput;
}

function contextOf(result: ReturnType<typeof executorRouteNudge>): string {
  return (result.hookSpecificOutput?.additionalContext as string) || '';
}

const BUILD_PROMPT =
  'fix the flaky retry logic in the upload endpoint and add a regression test for it';

describe('prompt/executor-route-nudge', () => {
  test('nudges on a build-shaped goal prompt', () => {
    const result = executorRouteNudge(makeInput(BUILD_PROMPT));
    expect(result.continue).toBe(true);
    const ctx = contextOf(result);
    expect(ctx).toContain('/ork:implement');
    expect(ctx).toContain('/ork:auto');
  });

  test('fires at most once per session', () => {
    const sessionId = `wf-nudge-once-${process.pid}-${Date.now()}`;
    const first = executorRouteNudge(makeInput(BUILD_PROMPT, sessionId));
    const second = executorRouteNudge(makeInput(BUILD_PROMPT, sessionId));
    expect(contextOf(first)).not.toBe('');
    expect(contextOf(second)).toBe('');
  });

  test('silent on short prompts', () => {
    expect(contextOf(executorRouteNudge(makeInput('fix the test')))).toBe('');
  });

  test('silent on non-build prompts', () => {
    expect(
      contextOf(
        executorRouteNudge(
          makeInput('explain how the retry logic in the upload endpoint decides to give up'),
        ),
      ),
    ).toBe('');
  });

  test('silent when the user already routes to a skill', () => {
    expect(
      contextOf(
        executorRouteNudge(
          makeInput('fix the flaky retry logic via /ork:fix-issue and report the root cause'),
        ),
      ),
    ).toBe('');
  });

  test('accepts polite/imperative openers', () => {
    const result = executorRouteNudge(
      makeInput('please implement cursor-based pagination for the sessions listing endpoint'),
    );
    expect(contextOf(result)).not.toBe('');
  });
});
